SELECT t.transplant, n.not_transplant, s.stay_id, s.intime, s.outtime, s.los, p.dod, c.composite_instability_score, percentile_cont(0.25) within GROUP (ORDER BY c.composite_instability_score) AS q25, percentile_cont(0.75) within GROUP (ORDER BY c.composite_instability_score) AS q75, COUNT(CASE WHEN l.itemid = 10155 AND l.value > 38.5 THEN 1 END) AS fever_events, COUNT(CASE WHEN l.itemid = 20002 AND l.value < 90 THEN 1 END) AS spo2_events, COUNT(CASE WHEN l.itemid = 20004 AND l.value > 20 THEN 1 END) AS rr_events FROM transplants t JOIN patients p ON t.subject_id = p.subject_id JOIN icustays s ON t.subject_id = s.subject_id JOIN labevents l ON s.stay_id = l.subject_id AND s.intime <= l.charttime AND s.outtime >= l.charttime JOIN composite_instability_scores c ON s.stay_id = c.stay_id AND s.intime <= c.charttime AND s.outtime >= c.charttime WHERE p.gender = 'M' AND p.anchor_age >= 57 AND p.anchor_age <= 67 AND s.intime <= 72 AND s.outtime >= 72 AND (t.transplant = TRUE OR t.transplant = FALSE) AND (n.not_transplant = TRUE OR n.not_transplant = FALSE) GROUP BY t.transplant, n.not_transplant, s.stay_id, s.intime, s.outtime, s.los, p.dod, c.composite_instability_score;